+    }
+
+    function DeleteConfirmDialog() {
+      return `
+        <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-copy">
+          <div class="dialog-panel">
+            <span class="dialog-kicker">Delete from library</span>
+            <h2 class="dialog-title" id="delete-dialog-title">Delete this image?</h2>
