+            <div class="dialog-actions">
+              <button type="button" class="button button-secondary dialog-button" id="cancel-delete" autofocus>
+                Cancel
+              </button>
+              <button type="button" class="button button-danger dialog-button" id="confirm-delete">
+                Delete image
+              </button>
+            </div>
+          </div>
+        </dialog>
+      `;
+    }
+
+    const state = { deleted: false };
+    document.body.innerHTML = App();
+
+    const appRoot = document.getElementById("app-root");
+    const dialog = document.getElementById("delete-dialog");
+
+    function renderPage() {
+      appRoot.innerHTML = ImagePreviewPage(imageRecord, state.deleted);
+      const trigger = document.getElementById("delete-trigger");
+      const statusMessage = document.getElementById("status-message");
+
+      if (trigger) {
+        trigger.addEventListener("click", () => {
+          dialog.showModal();
+        });
+      }
+
+      if (statusMessage && state.deleted) {
+        statusMessage.textContent = "Image deleted from your library.";
+      }
+    }
+
+    document.getElementById("cancel-delete").addEventListener("click", () => {
+      dialog.close("cancel");
+    });
+
+    document.getElementById("confirm-delete").addEventListener("click", () => {
+      state.deleted = true;
+      renderPage();
+      dialog.close("delete");
+    });
+
+    dialog.addEventListener("cancel", (event) => {
+      event.preventDefault();
+      dialog.close("cancel");
+    });
+
+    renderPage();
+  </script>
+</body>
