          </div>
        </article>
      `;
    }

    function ImageMetaPanel(image) {
      return `
        <aside class="sidebar" aria-labelledby="details-title">
          <h2 id="details-title">Image details</h2>
          <p>This layout uses a native modal dialog so keyboard focus moves into the confirmation panel and returns to the trigger, or the updated content after deletion, when the dialog closes.</p>
          <div class="stats">
