      renderPage();
      dialog.close("delete");
    });

    dialog.addEventListener("cancel", (event) => {
      event.preventDefault();
      dialog.close("cancel");
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "delete") {
        document.getElementById("empty-title")?.focus();
      }
    });

    renderPage();
  </script>
